import{_ as r,a0 as l,w as d,s as p,ao as i,I as a,x as t,a1 as n,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"學習在 Linux 上使用 JOE 文本編輯器 | LCTT x X-CMD","titleTemplate":false,"description":"學習在 Linux 上使用 JOE 文本編輯器 | LCTT (202101) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"學習在 Linux 上使用 JOE 文本編輯器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"學習在 Linux 上使用 JOE 文本編輯器 | LCTT (202101) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202101/20201228 Learn to use the JOE text editor on Linux","title":"學習在 Linux 上使用 JOE 文本編輯器","tag":"202101","desc":""},"relativePath":"202101/20201228 Learn to use the JOE text editor on Linux.md","filePath":"[post].md"}'),u={name:"202101/20201228 Learn to use the JOE text editor on Linux.md"};function m(E,e,f,x,g,J){const o=l("Link");return d(),p("div",null,[e[21]||(e[21]=i('<h1 id="學習在-linux-上使用-joe-文本編輯器" tabindex="-1">學習在 Linux 上使用 JOE 文本編輯器 <a class="header-anchor" href="#學習在-linux-上使用-joe-文本編輯器" aria-label="Permalink to “學習在 Linux 上使用 JOE 文本編輯器”">​</a></h1><blockquote><p>Joe&#39;s Own Editor （JOE）是一款簡單易學和使用的通用文本編輯器。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202101/07/233204ps2fl3fffgmxzxqg.jpg" alt=""></p><p>我很喜歡那些能讓你輕鬆學會如何使用的文本編輯器。GNU nano 是我最喜歡的例子：你啓動 nano，你會在整個會話的窗口底部看到一個最常用的命令列表。Joe&#39;s Own Editor（簡稱 <code>joe</code>）是另一個很好的例子。</p><p><code>joe</code> 編輯器使用了一個基於終端的界面，提供了簡單的文本編輯功能和一個易於訪問的幫助屏幕。它用 C 語言編寫，體積小，只對 libc 有硬性依賴（ncurses 是可選的），並且採用 GPL 許可證。</p><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3>',6)),a("p",null,[e[1]||(e[1]=t("在 Linux 上，你也許能在你的發行版軟件倉庫中找到 JOE。雖然它有點小眾，並不是所有的發行版都打包了它。如果是這樣的話，你可以從 ",-1)),n(o,{href:"https://joe-editor.sourceforge.io/"},{default:s(()=>[...e[0]||(e[0]=[t("SourceForge",-1)])]),_:1}),e[2]||(e[2]=t(" 下載源碼，然後自己編譯。這是個簡單的過程：",-1))]),e[22]||(e[22]=i(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./configure</span></span>
<span class="line"><span>$ make</span></span>
<span class="line"><span>$ sudo make install</span></span></code></pre></div><h3 id="使用-joe" tabindex="-1">使用 JOE <a class="header-anchor" href="#使用-joe" aria-label="Permalink to “使用 JOE”">​</a></h3>`,2)),a("p",null,[e[4]||(e[4]=t("據其作者介紹，JOE 的靈感來自於一個叫 WordStar 的應用和 ",-1)),n(o,{href:"https://opensource.com/article/20/12/emacs"},{default:s(()=>[...e[3]||(e[3]=[t("GNU Emacs",-1)])]),_:1}),e[5]||(e[5]=t("。它的大部分基本編輯鍵都與 WordStar 的快捷鍵相同，編輯器本身也在努力向 WordStar 靠攏。JOE 也有 GNU Emacs 的一些鍵綁定和功能。這種兩種靈感來源的混合有時會讓人迷惑，但話又説回來，在任何情況下，讓自己離開 Emacs（或你通常選擇的文本編輯器）都會讓人迷惑。重要的是，JOE 提供了幫助，而且很容易訪問。",-1))]),e[23]||(e[23]=i('<p>在 JOE 界面右上角，有一個持續的提示，你可以按 <code>Ctrl+K</code>，緊接着按 <code>H</code> 來查看幫助界面。這是一個切換鍵，所以一旦你激活它，幫助屏幕就會一直顯示在你的編輯器窗口頂部，直到用同樣的組合鍵（JOE 中的鍵盤符號為 <code>^KH</code>）解除。</p><h3 id="鍵盤快捷鍵" tabindex="-1">鍵盤快捷鍵 <a class="header-anchor" href="#鍵盤快捷鍵" aria-label="Permalink to “鍵盤快捷鍵”">​</a></h3><p>儘管 JOE 的作者在模擬 WordStar 用户體驗方面非常自豪，但我不得不承認，這對我來説是失落的。我從來沒有聽説過 WordStar，直到我在 JOE 的文檔中讀到了它，在我看來，它的鍵盤快捷鍵方案完全是任意的。有的用 <code>Ctrl+K</code> 作為轉義序列的前綴，有的用 <code>Esc</code> 作為前綴，還有的完全不需要轉義序列。我無法確定其中的邏輯。編輯操作和應用選項一樣，都有可能需要或不需要轉義序列，而且字母關聯對我來説是沒有什麼意義（例如，<code>Ctrl+K D</code> 代表<strong>另存為</strong>）。</p><p>幸運的是，JOE 可以讓你在鍵盤快捷鍵上作弊。安裝後，JOE 會悄悄為 <code>joe</code> 可執行文件創建一些符號鏈接。包括：</p><ul><li><code>jmacs</code> JOE 使用 Emacs 鍵綁定</li><li><code>jpico</code> JOE 使用 Pico （或 GNU nano） 鍵綁定</li><li><code>rjoe</code> JOE 的編輯只限於啓動時傳遞給 JOE 的文件</li><li><code>jstar</code> JOE 使用 WordStar 鍵綁定</li></ul><p><img src="https://opensource.com/sites/default/files/uploads/joe-jstar-31_days-joe-opensource.png" alt="Black terminal with white text showing WordStar key bindings" title="Black terminal with white text showing WordStar key bindings"></p><p>持久保留的幫助菜單仍然存在，所以如果你不清楚有哪些功能可以使用，可以通過屏幕右上方的幫助提示來參考。當然，在 Pico/nano 模式下，主要命令總是可見的。</p><h3 id="嘗試-joe" tabindex="-1">嘗試 JOE <a class="header-anchor" href="#嘗試-joe" aria-label="Permalink to “嘗試 JOE”">​</a></h3><p>JOE 並不是一個你永遠不會離開的文本編輯器，它不會成為你的 IDE、電子郵件客户端、網絡瀏覽器和文件管理器。事實上，它甚至可能不是你所有任務的主要文本編輯器。它專注於做好一件事，那就是成為一般的文本編輯。</p><p>JOE 擁有你所需要的所有基本功能，比如能夠快速瀏覽你的文本、能夠選擇文本、複製和粘貼等等。試試 JOE 吧，使用你喜歡的符號鏈接。</p><hr>',11)),a("p",null,[e[7]||(e[7]=t("via: ",-1)),n(o,{href:"https://opensource.com/article/20/12/joe"},{default:s(()=>[...e[6]||(e[6]=[t("https://opensource.com/article/20/12/joe",-1)])]),_:1})]),a("p",null,[e[12]||(e[12]=t("作者：",-1)),n(o,{href:"https://opensource.com/users/seth"},{default:s(()=>[...e[8]||(e[8]=[t("Seth Kenlon",-1)])]),_:1}),e[13]||(e[13]=t(" 選題：",-1)),n(o,{href:"https://github.com/lujun9972"},{default:s(()=>[...e[9]||(e[9]=[t("lujun9972",-1)])]),_:1}),e[14]||(e[14]=t(" 譯者：",-1)),n(o,{href:"https://github.com/geekpi"},{default:s(()=>[...e[10]||(e[10]=[t("geekpi",-1)])]),_:1}),e[15]||(e[15]=t(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:s(()=>[...e[11]||(e[11]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[18]||(e[18]=t("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[16]||(e[16]=[t("LCTT",-1)])]),_:1}),e[19]||(e[19]=t(" 原創編譯，",-1)),n(o,{href:"https://linux.cn/"},{default:s(()=>[...e[17]||(e[17]=[t("Linux中國",-1)])]),_:1}),e[20]||(e[20]=t(" 榮譽推出",-1))])])}const k=r(u,[["render",m]]);export{h as __pageData,k as default};
